insert into public.academy_course_structures
    (app_slug, tier, structure, content_version)
insert into public.academy_quiz_questions
    (app_slug, tier, scope, module_key, ord, prompt, options, answer_index, explanation)
values
  ('casingtubing', 'beginner', 'module', 'm01-what-a-casing-string-is', 1, 'What is a completed well, structurally?', '["A single lined hole of constant diameter from surface to the reservoir.", "A nest of steel pipes, each run inside the last one, with the innermost carrying the produced fluid.", "A cemented annulus surrounding an open hole, in which the steel is present only opposite the zones that need isolating.", "A drilled hole whose walls are stabilised chemically by the mud rather than mechanically, with steel used only at surface."]'::jsonb, 1, 'Each stage is drilled through the inside of the string above it, so the sizes step down with depth.'),
  ('casingtubing', 'beginner', 'module', 'm01-what-a-casing-string-is', 2, 'What is the surface casing there to do?', '["Isolate the reservoir from every zone above it for the life of the well.", "Provide the flow path for produced fluid, sealed to the production casing by a packer near the bottom of the string.", "Isolate a weak zone that would otherwise break down, or a high pressure zone that would otherwise flow into the well.", "Hold the top of the hole up and carry the wellhead and the blowout preventer stack."]'::jsonb, 3, 'It is a structural string first and a pressure containing one second.'),
  ('casingtubing', 'beginner', 'module', 'm01-what-a-casing-string-is', 3, 'How many of the four numbers describing a tubular are independent?', '["Two, because the inside diameter follows from the other two and the weight is essentially a rounded label.", "All four, since each is measured separately at the mill.", "Three, because the nominal weight cannot be derived from the geometry to the precision the published tables carry.", "One, because a nominal weight fixes the outside diameter, the wall and the inside diameter together in the API tables."]'::jsonb, 0, 'Outside diameter and wall are the pair the rating formulas use, and everything else follows or is a name.'),
  ('casingtubing', 'beginner', 'module', 'm01-what-a-casing-string-is', 4, 'Why does extra wall thickness carry a cost as well as a benefit?', '["It raises the steel cost of the string in proportion.", "It lowers the collapse rating, because a thicker wall pushes the pipe into a regime with a weaker published formula.", "It takes bore, and the bore is what the next hole section has to be drilled and run through.", "It increases the hanging weight, which reduces the tension safety factor at the top of the string in direct proportion."]'::jsonb, 2, 'Casing design looks for the lightest pipe that passes, not the strongest one available.'),
  ('casingtubing', 'beginner', 'module', 'm01-what-a-casing-string-is', 5, 'What does the number in a grade name such as L-80 give?', '["The maximum permitted hardness of the finished steel.", "The minimum yield strength in thousands of pounds per square inch, which is the only property the formulas read.", "The nominal wall thickness in hundredths of an inch, which combined with the letter fixes the whole geometry of the row.", "The internal yield pressure rating in hundreds of pounds per square inch, before the wall tolerance factor is applied."]'::jsonb, 1, 'The letter carries the manufacturing route and the chemistry, and the engine never reads it.'),
  ('casingtubing', 'beginner', 'module', 'm01-what-a-casing-string-is', 6, 'L-80 and N-80 both yield at 80 ksi. What follows for this engine?', '["They are the same pipe, because the yield strength is the only grade property any of the four formulas uses.", "Their collapse ratings differ but their burst ratings agree.", "The engine selects the more conservative of the two automatically, using the letter to decide which one that is.", "Their ratings differ by the ratio of their permitted hardness values, which is where the difference between them lives."]'::jsonb, 0, 'Substituting one for the other is a real error in sour service and no rating in this course would catch it.'),
  ('casingtubing', 'beginner', 'module', 'm01-what-a-casing-string-is', 7, 'The published yield strength of a grade is a minimum. What does that make every rating?', '["An average over the mill''s production for that grade.", "An upper bound, because the rating formulas are fitted to the best pipe in the qualification programme rather than the worst.", "A number with no defined statistical meaning, because a minimum yield combined with an empirical fit has neither bound.", "A lower bound on what the joint will actually do, which is the right direction for a design number."]'::jsonb, 3, 'Real pipe from the mill runs above the minimum, often well above it.'),
  ('casingtubing', 'beginner', 'module', 'm01-what-a-casing-string-is', 8, 'What does the burst rating assume about the pressure outside the pipe?', '["That it equals the mud hydrostatic at the shoe depth.", "That it equals the pore pressure of the formation the joint is opposite, which is why the rating varies down a string.", "That it is zero, so the rating is a differential quoted as though the outside were vented.", "That it is the same as the inside pressure, so the rating describes a balanced condition with no net differential at all."]'::jsonb, 2, 'Every rating in this tier is a single load acting alone, which is why there is a fourth combined check.'),
  ('casingtubing', 'beginner', 'module', 'm01-what-a-casing-string-is', 9, 'Why is the burst rating not a rupture pressure?', '["Because steel yields well before it tears, so passing the rating means permanent deformation rather than an opening.", "Because the rating is computed on the minimum wall.", "Because rupture requires a defect to grow, and the presence of a defect is a manufacturing question rather than a design one.", "Because the internal yield formula uses the outside diameter, which gives a smaller answer than the mean diameter would."]'::jsonb, 0, 'Yielding a casing string is already a failure for most purposes, so the distinction is about wording rather than margin.'),
  ('casingtubing', 'beginner', 'module', 'm01-what-a-casing-string-is', 10, 'Which of the four ratings is exact rather than empirical or tolerance adjusted?', '["The collapse rating, which is derived from first principles.", "The pipe body yield, which is the yield strength times the cross-sectional area of steel and nothing else.", "The joint strength, because the connection efficiency is measured directly on the connection rather than assumed.", "The burst rating, because the Barlow derivation is an exact statement of equilibrium for a cylinder under internal pressure."]'::jsonb, 1, 'Three of the four collapse formulas are fits to a test programme, and burst carries a wall tolerance factor.'),
  ('casingtubing', 'beginner', 'module', 'm01-what-a-casing-string-is', 11, 'What is wrong with the sentence ''this joint is rated to 65 MPa''?', '["Nothing, provided the grade is stated alongside it.", "It uses megapascals, and every rating in the published tables is quoted in pounds per square inch rather than in SI.", "It does not say which of the four ratings is meant, and burst and collapse on one joint can differ by a factor of two.", "It omits the design factor, without which a rating cannot be compared against any load the string will actually see."]'::jsonb, 2, 'A rating is the answer to a stated question, and the statement is the important half of it.'),
  ('casingtubing', 'beginner', 'module', 'm01-what-a-casing-string-is', 12, 'Two engineers compute the burst rating of the same joint. What should they get?', '["Different numbers, since each will apply their own factor.", "The same number only if they agree on the mud weight in the hole, which enters the rating through the buoyancy factor.", "The same number, which is why a rating works as a common language even where the individual value is approximate.", "The same number, because the formula requires no judgement once the four inputs are agreed."]'::jsonb, 3, 'Comparability is most of the value of a published rating, and it survives the rating being approximate.'),
  ('casingtubing', 'beginner', 'module', 'm01-what-a-casing-string-is', 13, 'What does the tubing string do that the casing strings do not?', '["Support the wellhead and the pressure control equipment.", "Carry the produced or injected fluid, running inside the production casing and usually sealed to it by a packer.", "Isolate the reservoir from the zones above it, which the production casing only does over the cemented interval.", "Provide the drilling conduit for the section below it, which is why its inside diameter constrains the next bit size."]'::jsonb, 1, 'It is also the only string in the well that is not cemented, which is the whole subject of the Expert tier.'),
  ('casingtubing', 'beginner', 'module', 'm01-what-a-casing-string-is', 14, 'None of the four ratings accounts for what, most importantly?', '["The presence of the other three loads at the same time, which is why the triaxial check exists at all.", "The temperature of the steel at the depth in question.", "The wear the drillstring will inflict on the inside of the pipe over the weeks the next section takes to drill.", "The manufacturing tolerance on the wall thickness, which is permitted to run 12.5 percent under the nominal value."]'::jsonb, 0, 'A real string never has the luxury of one load acting alone.'),
  ('casingtubing', 'beginner', 'module', 'm01-what-a-casing-string-is', 15, 'How many rows and grades does the catalog in this course carry?', '["Eighty four rows at three grades, as published.", "Twenty two casing rows only, since the six tubing rows are handled by a separate catalog with its own grade list.", "Twenty eight rows and ten grades, giving 280 combinations of geometry and steel.", "Ten rows at twenty eight grades, one row for each nominal outside diameter the drilling programme is likely to need."]'::jsonb, 2, 'Twenty two casing rows plus six tubing rows, and each can be ordered in any of the ten grades.'),
  ('casingtubing', 'beginner', 'module', 'm02-burst-and-tension', 1, 'Barlow''s formula gives the internal pressure at yield as what?', '["The yield strength times the wall divided by the inside radius.", "Twice the yield strength times the wall, divided by the outside diameter of the pipe.", "The yield strength times the ratio of the wall to the diameter, halved to account for the two walls carrying the load.", "Four times the yield strength times the wall over the diameter, since both walls carry the load over the projected area."]'::jsonb, 1, 'Split a cylinder along its axis and the pressure acts on the projected area while two walls hold it together.'),
  ('casingtubing', 'beginner', 'module', 'm02-burst-and-tension', 2, 'Where does the projected area in the Barlow derivation come from?', '["The circumference times the wall thickness.", "The inside cross-sectional area of the pipe, since that is where the pressurised fluid is actually in contact with steel.", "The diameter times the length, because cutting the cylinder along its axis leaves a flat rectangle for the pressure to push on.", "The diameter times the length, which is the area a half cylinder presents to the pressure inside it."]'::jsonb, 3, 'Cancelling the length is what leaves a formula with no length in it.'),
  ('casingtubing', 'beginner', 'module', 'm02-burst-and-tension', 3, 'What does the thin wall assumption in Barlow''s formula get wrong?', '["It puts the same hoop stress everywhere in the wall, where the real stress is highest at the bore and falls outward.", "It ignores the axial stress entirely.", "It uses the outside diameter, where a mean diameter would be closer to the exact answer for a thick walled cylinder.", "It assumes the pipe is perfectly round, which real casing is not, and ovality is what actually drives the difference."]'::jsonb, 0, 'The exact answer is the Lame solution, and Barlow is a few percent conservative at every ratio in this catalog.'),
  ('casingtubing', 'beginner', 'module', 'm02-burst-and-tension', 4, 'Why does the published burst rating carry a factor of 0.875?', '["Because it is the design factor applied to burst.", "Because Barlow overstates the hoop stress by about an eighth at the ratios of diameter to wall found in casing.", "Because API permits the wall to run up to 12.5 percent under nominal, so the rating is computed on the minimum wall.", "Because the yield strength quoted for a grade is an average, and the factor converts it to a minimum for design use."]'::jsonb, 2, 'It is a manufacturing tolerance and not a safety factor, and counting it twice is a real error.'),
  ('casingtubing', 'beginner', 'module', 'm02-burst-and-tension', 5, 'Where in the four ratings does the 12.5 percent wall tolerance NOT appear?', '["In pipe body yield, which uses a tolerance of its own.", "In collapse, because the API collapse formulas are fitted to test data on pipe that already carried the variation.", "In joint strength, because the connection efficiency already contains an allowance for the same manufacturing spread.", "In none of them, since the tolerance is a property of the pipe and therefore applies to every rating computed from it."]'::jsonb, 1, 'The tolerance is inside the collapse fit rather than applied on top of it, and there is no 0.875 in the collapse code.'),
  ('casingtubing', 'beginner', 'module', 'm02-burst-and-tension', 6, 'The pipe body yield of a joint is which product?', '["The yield strength times the cross-sectional area of steel, which is pi over four times the difference of the squared diameters.", "The yield strength times the wall times the circumference.", "The yield strength times the nominal weight per unit length divided by the density of steel, which recovers the same area.", "The internal yield pressure times the inside cross-sectional area, which is the force the pressure develops on the section."]'::jsonb, 0, 'It is the definition of yielding a bar in tension applied to a bar that happens to be hollow.'),
  ('casingtubing', 'beginner', 'module', 'm02-burst-and-tension', 7, 'Why does the pipe body yield carry no wall tolerance factor?', '["Because API applies tolerances only to pressure ratings.", "Because the area is computed from the inside and outside diameters, both of which are held to a tighter tolerance than the wall.", "Because a thin spot is a local failure initiator under pressure and is not one under an axial load spread over the section.", "Because the axial load is carried by the whole section, so a local thin spot is averaged out along the joint."]'::jsonb, 3, 'Burst is where a thin spot matters, and that is where the factor is applied.'),
  ('casingtubing', 'beginner', 'module', 'm02-burst-and-tension', 8, 'What is the joint strength in this engine?', '["The lowest of the four ratings for that joint.", "The pipe body yield reduced by the fraction of the wall removed to cut the thread, computed from the thread geometry.", "The pipe body yield multiplied by a single connection efficiency read from a small published table.", "The tensile capacity of the coupling, computed from its own outside diameter and the yield strength of the coupling stock."]'::jsonb, 2, 'It is a screening number, and a real design verifies against the manufacturer''s data sheet.'),
  ('casingtubing', 'beginner', 'module', 'm02-burst-and-tension', 9, 'Which connection efficiency does a short thread and coupling connection carry here?', '["Zero point seven five, so a quarter of the pipe body strength is given away at the thread.", "One, by design, as with buttress and premium connections.", "Zero point eight five, the same value the long thread and coupling connection carries in the same published table.", "Zero point nine, which is the customary allowance for the metal removed to cut a short tapered thread into the pipe wall."]'::jsonb, 0, 'Long thread gives up about fifteen percent and buttress and premium are designed to give up nothing.'),
  ('casingtubing', 'beginner', 'module', 'm02-burst-and-tension', 10, 'Why is the buttress connection efficiency exactly one?', '["Because buttress threads remove no metal from the wall.", "Because it is designed so that the pipe body yields before the connection does, which makes the pipe the weak point.", "Because the efficiency table normalises every connection against buttress, which is therefore one by construction.", "Because a buttress coupling is thicker than the pipe, and the coupling rather than the thread carries the axial load."]'::jsonb, 1, 'That is a design intent rather than a measurement, and a data sheet will state the real number.'),
  ('casingtubing', 'beginner', 'module', 'm02-burst-and-tension', 11, 'A connection can have plenty of tensile strength and still fail. How?', '["By yielding the pipe body above it in compression.", "By losing its efficiency at temperature, which the table does not account for and which falls faster than the pipe body does.", "By leaking, since leak resistance depends on the seal geometry and the make-up torque rather than on the tensile capacity.", "By leaking, because sealing is a separate rating that no efficiency captures and this catalog does not carry."]'::jsonb, 3, 'A real data sheet gives sealing pressures for both directions alongside the tensile and compressive ratings.'),
  ('casingtubing', 'beginner', 'module', 'm02-burst-and-tension', 12, 'Which ratings are exactly proportional to the grade?', '["All four, since the yield strength enters every formula.", "Burst, pipe body yield and joint strength, because each is the yield strength times a pure geometry factor.", "Burst and collapse, because both describe a pressure at which the wall reaches its yield stress under a hoop load.", "Pipe body yield only, since it is the one rating that is not adjusted by a tolerance factor or an efficiency factor."]'::jsonb, 1, 'Collapse does not, and on some pipes it does not depend on the grade at all.'),
  ('casingtubing', 'beginner', 'module', 'm02-burst-and-tension', 13, 'The K-55 and P-110 burst ratings of one row differ by what factor exactly?', '["About 1.36, the ratio their collapse ratings show.", "Two, less a small correction for the fact that the wall tolerance factor is applied differently at the two grades.", "Two, because 110 over 55 is two and the geometry factor multiplying the yield is identical on both.", "Something between 1.5 and 2 depending on the ratio of diameter to wall, which sets how much of the yield is mobilised."]'::jsonb, 2, 'Doubling the yield strength doubles both burst and pipe body yield, exactly and with no approximation.'),
  ('casingtubing', 'beginner', 'module', 'm02-burst-and-tension', 14, 'A string is collapse critical. What does buying a higher grade get you?', '["Somewhere between full proportional benefit and none at all, decided by which of the four collapse regimes the pipe is in.", "A proportional increase, as it does for burst.", "Nothing, because the collapse formulas are empirical fits and the yield strength does not appear in any of them.", "An increase of about a third, which is the ratio the plastic regime formula produces for a doubling of the yield strength."]'::jsonb, 0, 'The money may be better spent on wall thickness, and the regime is what tells you which.'),
  ('casingtubing', 'beginner', 'module', 'm02-burst-and-tension', 15, 'Which fix raises the tension capacity of a section?', '["A thicker wall only, since grade does not enter tension.", "A lower mud weight, because the buoyancy factor rises with the density of the fluid the string is immersed in.", "A higher grade, a thicker wall or a better connection, since all three enter the joint strength directly.", "A shorter section, because the joint strength is compared against the weight of everything hanging below the joint."]'::jsonb, 2, 'Finding out which of the four checks is closest to failing comes before choosing what to change.'),
  ('casingtubing', 'beginner', 'module', 'm03-the-four-collapse-regimes', 1, 'Why does collapse need four formulas where burst needs one?', '["Because API publishes one formula per grade family.", "Because a pipe squeezed from outside fails by genuinely different mechanisms depending on how thick its wall is.", "Because the external pressure can come from mud, cement, formation fluid or a squeeze job, and each needs its own treatment.", "Because the four formulas correspond to the four load cases in which a casing string is exposed to net external pressure."]'::jsonb, 1, 'Burst has one mechanism: the hoop stress reaches yield. Collapse has four.'),
  ('casingtubing', 'beginner', 'module', 'm03-the-four-collapse-regimes', 2, 'How does a very thick walled pipe fail under external pressure?', '["It goes oval and then flattens, with no yielding at all.", "It fails at the connection first, because the coupling has a larger diameter and therefore a larger projected area.", "The wall yields, and because that is a strength rather than a stability problem the collapse pressure scales with the grade.", "The wall yields in compression without buckling, so the collapse pressure is proportional to the yield strength."]'::jsonb, 3, 'That is the yield regime, the thickest of the four and the only one that is a pure strength calculation.'),
  ('casingtubing', 'beginner', 'module', 'm03-the-four-collapse-regimes', 3, 'What happens first in a slender, thin walled joint as the squeeze on it rises?', '["It buckles elastically and goes oval long before anything yields, so the steel strength never enters the answer.", "It yields at the bore, where the hoop stress is highest.", "It fails progressively from the connection outward, because the thread root is the thinnest section of the whole joint.", "It buckles, but only after the wall has yielded locally at the point of greatest ovality, which is where the buckle initiates."]'::jsonb, 0, 'Nothing has yielded, so how strong the steel is has not yet come into it.'),
  ('casingtubing', 'beginner', 'module', 'm03-the-four-collapse-regimes', 4, 'What are the plastic and transition collapse formulas?', '["Exact solutions for an ovalised elastic-plastic cylinder.", "Interpolations between the yield and elastic formulas, weighted by where the pipe sits between the two boundaries.", "Empirical fits to a large collapse test programme, filling the gap between the yield and elastic calculations.", "Derivations from plasticity theory that account for the residual stress left in the pipe by the manufacturing process."]'::jsonb, 2, 'They are not derived from anything, and they carry the scatter of the test population with them.'),
  ('casingtubing', 'beginner', 'module', 'm03-the-four-collapse-regimes', 5, 'Which single number decides the collapse regime?', '["The wall thickness in absolute terms.", "The ratio of outside diameter to wall thickness, and nothing else about the pipe enters the choice.", "The product of the yield strength and the wall thickness, which sets how much compression the section can carry.", "The ratio of the inside diameter to the wall, which is the slenderness the buckling calculation actually depends on."]'::jsonb, 1, 'Stability problems are governed by slenderness rather than by absolute size.'),
  ('casingtubing', 'beginner', 'module', 'm03-the-four-collapse-regimes', 6, 'Why is the ratio of diameter to wall the right variable and not the wall itself?', '["Because a pipe scaled up in every dimension keeps the same ratio and buckles at the same external pressure.", "Because the wall is not known to sufficient precision.", "Because the ratio is dimensionless and the collapse formulas were published in field units that would otherwise not transfer.", "Because the wall enters the formulas only through the steel area, and the area already carries the diameter with it."]'::jsonb, 0, 'That scale invariance is exact in the elastic regime and lost in the other three, where the yield strength enters as well.'),
  ('casingtubing', 'beginner', 'module', 'm03-the-four-collapse-regimes', 7, 'The 20 inch 106.5 lb/ft row has a ratio of exactly 40. Why exactly?', '["Because API rounds every published ratio to the nearest ten.", "Because the row was selected for the catalog on the grounds that it makes a convenient landmark in the middle of the range.", "Because a ratio of forty is the boundary between the transition and elastic regimes for the grades in common surface use.", "Because its wall is exactly half an inch and its diameter exactly twenty, which is an accident of the published table."]'::jsonb, 3, 'It is a convenient landmark and nothing more.'),
  ('casingtubing', 'beginner', 'module', 'm03-the-four-collapse-regimes', 8, 'Which of the four collapse formulas contains no yield strength?', '["The transition one, which depends on geometry only.", "The plastic one, since its coefficients absorb the grade dependence into the fitted constants rather than carrying it openly.", "The elastic one, which is a constant divided by the ratio times the square of the ratio less one.", "None of them, because every published collapse formula must reduce to a yield calculation at a sufficiently thick wall."]'::jsonb, 2, 'A pipe that buckles elastically has not yielded anywhere, so the strength has not entered.'),
  ('casingtubing', 'beginner', 'module', 'm03-the-four-collapse-regimes', 9, 'Why does the engine convert to psi inside the collapse function?', '["Because the 5C3 coefficient polynomials are the fit, and there is no SI form of them that does not require a refit.", "Because the rest of the engine works in field units.", "Because the yield strength is published in ksi and converting it once at the catalog would lose precision downstream.", "Because the elastic formula''s constant of 46950000 is dimensionless, and the other three must be brought into line with it."]'::jsonb, 0, 'It is the single sanctioned unit boundary in the module, and the header says so.'),
  ('casingtubing', 'beginner', 'module', 'm03-the-four-collapse-regimes', 10, 'The three regime boundaries are functions of what?', '["The ratio of diameter to wall for the pipe in question.", "The yield strength alone, so they belong to the grade and no dimension of the pipe appears in any of them.", "The yield strength and the wall thickness together, which is why a heavier row of the same grade has different boundaries.", "The yield strength and the outside diameter, since the empirical fits were performed separately for each nominal size."]'::jsonb, 1, 'The pipe then contributes exactly one number, its own ratio, and the regime follows.'),
  ('casingtubing', 'beginner', 'module', 'm03-the-four-collapse-regimes', 11, 'What happens to the three regime boundaries as the grade rises?', '["All three rise, in proportion to the yield strength.", "The yield boundary falls and the other two rise, which is what widens the plastic regime for the higher grades.", "All three fall, so a strong pipe reaches elastic collapse at a lower slenderness than a weak one does.", "They are unchanged, because the boundaries are geometric and only the collapse values computed from them move."]'::jsonb, 2, 'Strong steel does not stop a thin pipe buckling. It means the pipe reaches buckling before it reaches yielding.'),
  ('casingtubing', 'beginner', 'module', 'm03-the-four-collapse-regimes', 12, 'The engine''s test probes either side of each boundary at every grade. What must it find?', '["That the regime name is the same on both sides.", "That the collapse pressure jumps by less than the published tolerance, which is what continuity means in an empirical fit.", "That the collapse pressure rises monotonically across the boundary, since a thinner wall must always collapse sooner.", "That the two adjacent formulas give the same collapse pressure, because the system is built to be continuous there."]'::jsonb, 3, 'It is the strongest single check that the coefficient set has been transcribed correctly.'),
  ('casingtubing', 'beginner', 'module', 'm03-the-four-collapse-regimes', 13, 'How do you read the collapse regime off a catalog row?', '["Look up the regime in the published API table for the row.", "Compute the ratio of diameter to wall, read the three boundaries for the grade, and place the ratio among them.", "Compute the collapse pressure with all four formulas and take whichever of the four answers comes out the smallest.", "Compare the wall thickness against the published minimum for the grade, which is what the regime boundaries encode."]'::jsonb, 1, 'Two steps, and the answer tells you whether a higher grade would buy any collapse resistance at all.'),
  ('casingtubing', 'beginner', 'module', 'm03-the-four-collapse-regimes', 14, 'At L-80 the 20 inch 133 lb/ft row is elastic and at K-55 it is in transition. Why?', '["Because the transition to elastic boundary is higher at K-55, and the pipe''s fixed ratio falls on the other side of it.", "Because the pipe''s ratio changes with the grade ordered.", "Because the L-80 collapse value is higher, and a higher collapse value always means a regime further up the sequence.", "Because the K-55 fit was performed on a different test population, whose scatter placed the boundary at a higher slenderness."]'::jsonb, 0, 'Nothing about the pipe changed. The boundary moved past it.'),
  ('casingtubing', 'beginner', 'module', 'm03-the-four-collapse-regimes', 15, 'Why establish the regime before quoting a collapse rating?', '["Because the rating cannot be computed without it.", "Because the design factor applied to collapse depends on the regime, being lower in the two empirical regimes than elsewhere.", "Because two engineers who agree on the number and disagree on the regime will give opposite advice on how to fix it.", "Because the regime decides whether the wall tolerance factor of 0.875 has to be applied to the collapse value as well."]'::jsonb, 2, 'It is the first thing to establish about any collapse critical joint.'),
  ('casingtubing', 'beginner', 'module', 'm04-combined-loading', 1, 'Why does axial tension reduce the collapse resistance of a joint?', '["Because tension thins the wall by the Poisson effect.", "Because yielding depends on the difference between principal stresses, and pulling one up while pushing another down widens it.", "Because the tension is carried by the same steel that resists the hoop load, so less of the section is available for it.", "Because a string in tension is straighter, and a straight pipe has less residual curvature to resist the ovalising pressure."]'::jsonb, 1, 'The wall under external pressure carries a compressive hoop stress, and an axial tension is the worst thing to add to it.'),
  ('casingtubing', 'beginner', 'module', 'm04-combined-loading', 2, 'How does API handle combined loading in collapse?', '["By adding a fifth formula for the combined condition.", "By reducing the published collapse rating by a fixed percentage that depends on the regime the pipe is in at zero load.", "By computing an axial adjusted yield and handing it to the four published formulas without altering any of them.", "By computing an axial adjusted yield strength and feeding it to the same four formulas, unchanged."]'::jsonb, 3, 'It is pragmatic rather than derived, and it has one consequence the whole of module five depends on.'),
  ('casingtubing', 'beginner', 'module', 'm04-combined-loading', 3, 'The axial adjusted yield formula is the square root of one less three quarters r squared, less half r. Where does that shape come from?', '["It is the von Mises ellipse solved as a quadratic for the hoop stress, taking the compressive root.", "It is an empirical fit to combined loading tests.", "It is the Tresca criterion rearranged, which gives a linear reduction that the published curve then rounds into an ellipse.", "It is the ratio of the remaining elastic section to the full section, after the axial load has yielded part of the wall."]'::jsonb, 0, 'The coefficients of three quarters and one half fall out of the quadratic rather than being fitted.'),
  ('casingtubing', 'beginner', 'module', 'm04-combined-loading', 4, 'Applying tension does two things to the collapse calculation. What are they?', '["It lowers the value and lowers the boundaries with it.", "It lowers the value and lowers the design factor, since a combined load is better characterised than a single one.", "It lowers the collapse value and it raises all three regime boundaries, so the pipe can change regime.", "It raises the boundaries only, leaving the value alone until the pipe has actually crossed into a different regime."]'::jsonb, 2, 'The boundaries fall as the yield rises, so derating the yield sends them the other way.'),
  ('casingtubing', 'beginner', 'module', 'm04-combined-loading', 5, 'Which direction does tension move a pipe through the four regimes?', '["Upward, toward the elastic regime, as it gets weaker.", "Downward, toward the yield regime, because a derated pipe behaves like a lower grade one.", "It does not move at all, because the regime is decided by the ratio of diameter to wall and tension changes neither.", "Downward at low tension and upward at high tension, because the adjusted yield curve is not monotone across its range."]'::jsonb, 1, 'Low grade pipe reaches its boundaries at higher slenderness than high grade pipe does.'),
  ('casingtubing', 'beginner', 'module', 'm04-combined-loading', 6, 'The catalog census moves from 42 to 71 in the yield regime at forty percent tension. What moved?', '["Nothing about the geometry. The boundaries rose because the effective yield fell, and 29 pipes crossed one.", "The wall thickness, through the Poisson effect.", "The published fits, because the coefficient polynomials are evaluated at the adjusted yield rather than the nominal one.", "The ratio of diameter to wall, which rises under tension as the pipe elongates and its diameter contracts accordingly."]'::jsonb, 0, 'Nineteen pipes also left the elastic regime over the same span.'),
  ('casingtubing', 'beginner', 'module', 'm04-combined-loading', 7, 'In which regime does the collapse derating exactly equal the yield derating?', '["The elastic regime, where both are zero by definition.", "The plastic regime, which is where about half the catalog sits and where the fitted coefficients preserve proportionality.", "The transition regime, because its formula was constructed to interpolate linearly between the two neighbouring ones.", "The yield regime, because that formula is linear in the yield strength and passes the derating straight through."]'::jsonb, 3, 'On a 7 inch 35 lb/ft joint at K-55 the two columns add to one at every fraction, to fifteen decimal places.'),
  ('casingtubing', 'beginner', 'module', 'm04-combined-loading', 8, 'How much collapse does a pipe in the elastic regime lose to axial tension?', '["About a third of what a yield regime pipe would lose.", "A small amount, because the elastic formula''s constant is fitted to a population that included pipe under axial load.", "None at all, exactly, for as long as it stays in that regime, because the formula contains no yield strength.", "The same as any other regime, since the derating is applied to the published rating after the regime has been chosen."]'::jsonb, 2, 'Not a small amount. Nothing, to the last bit of the double.'),
  ('casingtubing', 'beginner', 'module', 'm04-combined-loading', 9, 'A 20 inch 94 lb/ft joint at K-55 is immune to tension up to about 0.5465 of yield. What happens then?', '["The elastic boundary finally climbs past its ratio of 45.662100456621005 and it enters the transition regime.", "Its adjusted yield reaches zero and the rating collapses.", "The pipe reaches the plastic regime directly, skipping transition, because the two boundaries cross at that fraction.", "The published rating stops applying, because the collapse fit was performed at axial loads below half of the yield strength."]'::jsonb, 0, 'Even then it loses only 0.003124397190863104 of its collapse at a fraction of 0.6.'),
  ('casingtubing', 'beginner', 'module', 'm04-combined-loading', 10, 'What does the classic worry about the top joint being squeezed and stretched at once depend on?', '["The mud weight, through the buoyancy factor.", "The collapse regime, because on an elastically collapsing string the tension costs no collapse resistance at all.", "The connection efficiency, since a threaded connection is where both the axial and the radial load concentrate together.", "The length of the string, because the axial stress at the top rises with it while the external pressure there does not."]'::jsonb, 1, 'It is a real worry for a thick production casing and a non-worry for a thin surface one.'),
  ('casingtubing', 'beginner', 'module', 'm04-combined-loading', 11, 'The engine applies the derating only for positive axial stress. Why?', '["Because compression cannot occur in a hanging string.", "Because the adjusted yield formula returns a complex number for a negative ratio, which the engine cannot represent.", "Because API does not credit compression, so a section in compression keeps its undegraded rating.", "Because compression raises the collapse resistance by so much that including it would make the check meaningless."]'::jsonb, 2, 'It is written as a maximum against zero, which makes the choice visible in one character.'),
  ('casingtubing', 'beginner', 'module', 'm04-combined-loading', 12, 'What does the engine return when the axial stress reaches the yield strength?', '["An exception, which aborts the string evaluation.", "The elastic collapse value, since that formula does not contain the yield strength and therefore remains valid there.", "A very small positive number, obtained by clamping the adjusted yield at a floor so that the polynomials stay finite.", "A collapse pressure of zero, with a regime named yield-exhausted rather than one of the four physical ones."]'::jsonb, 3, 'The fifth name is a flag, and it travels with the answer rather than being logged somewhere and lost.'),
  ('casingtubing', 'beginner', 'module', 'm04-combined-loading', 13, 'Why would clamping to the elastic value be the most dangerous of the wrong answers?', '["Because it would be too large by several orders of magnitude.", "Because it is plausible: the answer would look like a normal collapse rating and would be entirely wrong.", "Because the elastic formula is the only one whose published fit does not extend to the axial loads in question.", "Because it would make the collapse safety factor infinite, which any downstream report would immediately reject as absurd."]'::jsonb, 1, 'Throwing aborts a whole evaluation and a small positive number wears the clothes of a computed result.'),
  ('casingtubing', 'beginner', 'module', 'm04-combined-loading', 14, 'What does an engine that computes a number for every input lose?', '["The ability to tell the caller which of two situations it is in, which makes it less useful rather than more.", "Nothing, provided the numbers are all finite.", "Only performance, since the guard clauses that would distinguish the cases cost time on every call through the function.", "The ability to be tested, because a function with no error paths has no branches for a test suite to exercise separately."]'::jsonb, 0, 'Every engine in this suite is built to say which of the two it is doing.'),
  ('casingtubing', 'beginner', 'module', 'm04-combined-loading', 15, 'At forty percent of yield the 9-5/8 inch 47 lb/ft joint loses 9.6 percent at P-110 and 17.6 at K-55. What does that show?', '["That the higher grade is closer to its elastic boundary.", "That the derating depends on the absolute axial stress rather than on its ratio to the yield strength of the grade.", "That the weaker grade is hurt more by the same fractional tension, even though both are in the plastic regime.", "That the two pipes are in different regimes, which is what makes the two percentages differ by roughly a factor of two."]'::jsonb, 2, 'The adjusted yield fraction is the same for both, and how much of it reaches the collapse value is not.'),
  ('casingtubing', 'beginner', 'module', 'm05-reading-a-rating-table', 1, 'The 20 inch 94 lb/ft row gives one collapse value at all ten grades. Why?', '["Because API publishes one collapse value per nominal size.", "Because its ratio of 45.662100456621005 puts it above the elastic boundary at every grade in the catalog.", "Because the catalog stores a single collapse figure per row and applies the grade only to the burst and tension ratings.", "Because the collapse fit was performed on 20 inch pipe of one grade and extrapolated to the others without adjustment."]'::jsonb, 1, 'All ten collapse elastically, and the elastic formula has no yield strength in it.'),
  ('casingtubing', 'beginner', 'module', 'm05-reading-a-rating-table', 2, 'Over the same ten grades, what does the burst rating on that row do?', '["It spans a factor of exactly 3.125, which is the ratio of the Q-125 yield strength to the H-40 one.", "It also stays flat, for the same reason collapse does.", "It rises by about a third, which is the same proportion the collapse rating rises by on a thicker walled row of the same size.", "It spans a factor of about two, which is the ratio between the highest and lowest grades in common use for surface casing."]'::jsonb, 0, 'Pipe body yield spans the same factor, and collapse spans nothing at all.'),
  ('casingtubing', 'beginner', 'module', 'm05-reading-a-rating-table', 3, 'How many of the 28 catalog rows give the same collapse at all ten grades?', '["Three, all of them 20 inch surface casing rows.", "None, because at least one grade in the catalog is always thick enough relative to the pipe to reach the plastic regime.", "Exactly one, the 20 inch 94 lb/ft row, and the 20 inch 106.5 row very nearly manages it as well.", "Two, the 20 inch 94 and 106.5 rows, both of which are elastic at every grade the catalog carries for them."]'::jsonb, 2, 'On the 106.5 row only H-40 breaks the pattern, because it is already in transition at a ratio of exactly forty.'),
  ('casingtubing', 'beginner', 'module', 'm05-reading-a-rating-table', 4, 'Why is a grade independent collapse rating not a defect in the model?', '["Because the difference is smaller than the published tolerance.", "Because API deliberately publishes one collapse value per geometry, and grade dependence is added only above a set wall.", "Because the elastic regime applies only to pipe with a ratio above forty, and no production casing is that slender.", "Because a pipe that buckles inward has not yielded anywhere, so how strong the steel is has not yet come into it."]'::jsonb, 3, 'The buckling pressure is set by stiffness and geometry, and stiffness is essentially the same for every grade of steel.'),
  ('casingtubing', 'beginner', 'module', 'm05-reading-a-rating-table', 5, 'Strength varies by a factor of three across the grade table. What does not vary?', '["The density, which is why the weights are the same.", "Young''s modulus, which is essentially identical for every grade of steel and is what buckling actually depends on.", "The Poisson ratio, which is what sets the ballooning factor and therefore the length change under internal pressure.", "The thermal expansion coefficient, which is why a thermal force on a tubing string does not depend on the grade ordered."]'::jsonb, 1, 'That is the real content of the finding, and everything else follows from it.'),
  ('casingtubing', 'beginner', 'module', 'm05-reading-a-rating-table', 6, 'A 20 inch surface string is collapse critical. What does ordering P-110 instead of K-55 buy?', '["Nothing in collapse, because both are elastic there, while roughly doubling the price of the steel.", "Twice the collapse rating and twice the burst rating.", "About a third more collapse resistance, since the higher grade moves the pipe closer to the transition regime boundary.", "Nothing at zero tension, and a proportional gain once the string is hanging, because tension reintroduces the grade."]'::jsonb, 0, 'The only thing that buys collapse in the elastic regime is wall thickness.'),
  ('casingtubing', 'beginner', 'module', 'm05-reading-a-rating-table', 7, 'What does a higher grade buy on a pipe that collapses elastically?', '["A higher collapse rating, once the pipe is in tension.", "A lower design factor, because the published rating for a higher grade carries less scatter from the test programme.", "Immunity to tension: it takes more derating before the elastic boundary climbs past that pipe''s own ratio.", "A larger bore, because a higher grade meets the same rating at a thinner wall and therefore leaves more room inside."]'::jsonb, 2, 'H-40 leaves the elastic regime at about 27 percent of yield and Q-125 at about 84.'),
  ('casingtubing', 'beginner', 'module', 'm05-reading-a-rating-table', 8, 'Why does a higher grade stay immune to tension for longer?', '["Because a higher grade has a lower ratio of diameter to wall.", "Because the boundary is computed from the adjusted yield, and a higher starting yield takes more derating to reach the same value.", "Because the adjusted yield curve is flatter at high yield strengths, so the same fraction of tension costs less absolute yield.", "Because the elastic boundary is proportional to the yield strength, so it starts further away from the pipe''s own ratio."]'::jsonb, 1, 'H-40 only has to lose about a quarter of its yield. Q-125 has to lose most of it.'),
  ('casingtubing', 'beginner', 'module', 'm05-reading-a-rating-table', 9, 'Which catalog number is a label rather than a computed quantity?', '["The wall thickness, which is derived from the other two.", "The inside diameter, which the API tables round independently and which no rating formula in the course reads directly.", "The nominal weight, since it is close to the steel area times the density of steel but rounded differently on every row.", "The nominal weight, which is a rounded published figure and is used only for the hanging weight."]'::jsonb, 3, 'The wall is the number every rating actually uses.'),
  ('casingtubing', 'beginner', 'module', 'm05-reading-a-rating-table', 10, 'The catalog''s own integrity test allows the wall and inside diameter to miss the outside diameter by up to what?', '["Five millimetres, which is the API rounding tolerance and deliberately not a tighter one.", "A tenth of a millimetre, as with any machined dimension.", "Nothing at all, because the inside diameter is defined as the outside diameter less twice the wall by construction.", "Twelve and a half percent of the wall, which is the same tolerance the burst rating already carries in its 0.875 factor."]'::jsonb, 0, 'The published table rounds the wall and the inside diameter separately, so they do not reconstruct exactly.'),
  ('casingtubing', 'beginner', 'module', 'm05-reading-a-rating-table', 11, 'Which number does this catalog not carry, that a real one would?', '["The nominal weight in pounds per foot.", "The connection efficiency, which in a real catalog is attached to the row rather than looked up in a separate table.", "The drift diameter, which is the largest mandrel guaranteed to pass and is smaller than the nominal bore.", "The minimum wall thickness, since the published tables give only the nominal wall and leave the tolerance to be applied."]'::jsonb, 2, 'Anything run through the casing is sized against the drift, not against the inside diameter.'),
  ('casingtubing', 'beginner', 'module', 'm05-reading-a-rating-table', 12, 'What is the connection efficiency table in this catalog described as, by the catalog itself?', '["Manufacturer ratings for the named connection types.", "Nominal planning level values that are customary screening figures rather than connection specific ratings.", "Lower bounds derived from a published survey of connection test data across the major thread licensors in the industry.", "Values measured on the specific connections used in the goldens, and therefore exact for those and indicative elsewhere."]'::jsonb, 1, 'A real connection data sheet gives six numbers where the table gives one.'),
  ('casingtubing', 'beginner', 'module', 'm05-reading-a-rating-table', 13, 'Which of these does the collapse rating not account for?', '["Ovality and residual stress from manufacture, both of which reduce collapse resistance and are properties of the joint.", "The ratio of diameter to wall, which it uses directly.", "The yield strength of the grade, which enters three of the four regime formulas and none of the boundary calculations.", "The axial load, which the combined loading adjustment brings in through a modified yield strength fed to the same formulas."]'::jsonb, 0, 'The formulas also assume the pipe is round and uniform, and real pipe is neither.'),
  ('casingtubing', 'beginner', 'module', 'm05-reading-a-rating-table', 14, 'Why is a screening calculation still worth doing?', '["Because it gives the same answer as a full analysis.", "Because the omissions it makes are individually small, so the total error stays inside the design factors already applied.", "Because it narrows a hundred rows to two or three, and the elimination it performs is what the later verification needs.", "Because it is cheap, conservative in a stated way, and comparable, so a ranking it produces is trustworthy."]'::jsonb, 3, 'It has done its job if it eliminates the right ninety percent. It has not made the decision.'),
  ('casingtubing', 'beginner', 'module', 'm05-reading-a-rating-table', 15, 'What is the single most important thing about a grade name that no formula here reads?', '["Its nominal weight, which the letter does not encode.", "Its Young''s modulus, which varies enough between grades to matter for the elastic collapse formula but is taken as constant.", "Whether it is qualified for hydrogen sulphide service, which is a chemistry and hardness question rather than a strength one.", "The mill that produced it, since seamless and welded pipe of the same grade carry different collapse test populations."]'::jsonb, 2, 'Choosing N-80 where L-80 was specified is a real error and this course would not catch it.'),
  ('casingtubing', 'beginner', 'module', 'm06-the-associate-reading', 1, 'Summarising the Associate tier: how do the four ratings divide?', '["All four scale in proportion with the grade ordered.", "Three are the steel strength times a pure geometry factor, and the fourth depends on which of four formulas applies.", "Two are exact and two are empirical, and the two empirical ones both carry a manufacturing tolerance factor of 0.875.", "Three are pressures and one is a force, which is why only three of them can be compared against a single load case."]'::jsonb, 1, 'Burst, pipe body yield and joint strength scale exactly. Collapse sometimes does not scale at all.'),
  ('casingtubing', 'beginner', 'module', 'm06-the-associate-reading', 2, 'A capstone asks for a rating at a grade the lessons never ran. What has to change in your method?', '["The collapse formulas, which are fitted per grade family.", "The regime boundaries, which must be interpolated between the two nearest published grades before the pipe can be placed.", "Nothing about the formulas, though the three regime boundaries must be recomputed because they belong to the grade.", "Nothing at all, because every formula takes the yield strength as a number and no formula reads a grade name."]'::jsonb, 3, 'The one lookup that reads a name returns a number of pascals, and everything downstream sees only that.'),
  ('casingtubing', 'beginner', 'module', 'm06-the-associate-reading', 3, 'Working a rating capstone, which field should you compute first and why?', '["The regime boundary, because knowing the regime tells you in advance how much the tension derating should cost.", "The burst rating, because it is the simplest formula.", "The joint strength, because it depends on the pipe body yield and therefore fixes two of the six fields at once.", "The collapse rating under tension, because everything else can be checked against it once the adjusted yield is known."]'::jsonb, 0, 'It also tells you whether a higher grade would have helped, which is the engineering question behind the arithmetic.'),
  ('casingtubing', 'beginner', 'module', 'm06-the-associate-reading', 4, 'A burst answer comes out 14.3 percent high. What was almost certainly left out?', '["The connection efficiency for the stated connection.", "The conversion from psi to pascals, which would leave an answer wrong by a factor of about 6895 rather than by a seventh.", "The wall tolerance factor of 0.875, since one over 0.875 is about 1.143.", "The axial derating, which reduces the yield strength handed to the formula and therefore the pressure it returns."]'::jsonb, 2, 'It is a manufacturing tolerance, applied to burst and to nothing else.'),
  ('casingtubing', 'beginner', 'module', 'm06-the-associate-reading', 5, 'A collapse answer comes out about 6895 times too small. What happened?', '["The wall was entered in inches rather than metres.", "The value came out of the coefficient polynomials in psi and was never converted back to pascals.", "The yield strength was entered in ksi rather than pascals, which propagates through the polynomials as a linear scaling.", "The adjusted yield was used in place of the nominal one, and the axial fraction supplied was very close to unity."]'::jsonb, 1, 'That is not a tolerance error, it is a different quantity, and it is the easiest mistake to make in the whole tier.'),
  ('casingtubing', 'beginner', 'module', 'm06-the-associate-reading', 6, 'The plastic to transition boundary is a dimensionless number around twenty. What is it a ratio of?', '["Two lengths, the outside diameter over the wall thickness, so it is neither a pressure nor a percentage.", "Two pressures, the plastic and transition collapse values.", "The yield strength to the elastic modulus, which is the dimensionless group that governs when buckling precedes yielding.", "The adjusted yield to the nominal yield, which is what the combined loading adjustment reduces the strength by."]'::jsonb, 0, 'Every one of the three boundaries is a value of that same ratio.'),
  ('casingtubing', 'beginner', 'module', 'm06-the-associate-reading', 7, 'A joint strength answer equals the pipe body yield exactly. What does that tell you?', '["The grade was entered wrongly, since the two never match.", "The pipe body yield was reused by mistake, because no connection in the published table carries an efficiency of exactly one.", "The connection is short thread, whose efficiency of 0.75 rounds to one at the precision the published tables are quoted to.", "The connection used has an efficiency of one, so it is buttress, premium or an upset tubing connection."]'::jsonb, 3, 'Long thread gives 0.85 and short thread 0.75, and both would show at once.'),
  ('casingtubing', 'beginner', 'module', 'm06-the-associate-reading', 8, 'Which two ratings share a single yield lookup and a single area?', '["Burst and collapse, both of which are pressures.", "Burst and pipe body yield, since both are the yield strength multiplied by a factor that depends only on the geometry.", "Pipe body yield and joint strength, since the second is the first multiplied by an efficiency.", "Collapse and joint strength, because the axial derating in the first is expressed as a fraction of the second."]'::jsonb, 2, 'Getting the area wrong therefore costs two fields rather than one.'),
  ('casingtubing', 'beginner', 'module', 'm06-the-associate-reading', 9, 'A collapse rating under tension comes out equal to the one without tension. When is that correct?', '["Never, since tension always reduces the collapse value.", "When the pipe is in the elastic regime and stays there, because that formula contains no yield strength.", "When the axial stress supplied is below ten percent of the yield strength, where the adjusted yield rounds to the nominal one.", "When the pipe is in the yield regime, where the derating cancels against the rise in the regime boundary above the pipe."]'::jsonb, 1, 'On a thick joint in the plastic regime the two should differ, and equality there means an input was dropped.'),
  ('casingtubing', 'beginner', 'module', 'm06-the-associate-reading', 10, 'Why compute a rating at a second grade even when only one is asked for?', '["Because the ratio of burst to yield strength must come out the same at both, which is a free check on the geometry.", "Because the capstone grades both answers together.", "Because the regime boundaries can only be located by comparing two grades, since a single grade gives one set of three.", "Because the collapse formulas require two grades to bracket the pipe before the correct regime can be identified for it."]'::jsonb, 0, 'Any pure geometry factor that changes between grades means the geometry was entered differently the second time.'),
  ('casingtubing', 'beginner', 'module', 'm06-the-associate-reading', 11, 'A 13-3/8 inch joint''s collapse comes out above the 9-5/8 inch family''s values. What does that suggest?', '["Nothing, since collapse is not ordered by diameter.", "That the 13-3/8 inch joint is in the yield regime while the 9-5/8 inch ones are elastic, which reverses the usual order.", "An input error, because the larger pipe is more slender and should sit below the smaller family, not above it.", "That the grade entered for the 13-3/8 inch joint was higher, which raises collapse in every regime except the elastic one."]'::jsonb, 2, 'A sanity check on the size of an answer catches errors that no tolerance would.'),
  ('casingtubing', 'beginner', 'module', 'm06-the-associate-reading', 12, 'In one sentence, what is the Associate tier''s central finding?', '["That every rating scales in proportion with the grade.", "That the manufacturing wall tolerance of 12.5 percent is the largest single correction applied anywhere in the tier.", "That the connection is always the weakest part of the string, so joint strength is the rating that governs a design.", "That collapse behaves nothing like the other three ratings, and which of four formulas it uses decides how."]'::jsonb, 3, 'Everything else in the tier is a consequence of that one asymmetry.'),
  ('casingtubing', 'beginner', 'module', 'm06-the-associate-reading', 13, 'What is an Associate in this course certified as able to produce?', '["Sign off a casing string against its service loads.", "Produce four defensible ratings for any joint in the catalog at any grade and under any axial load.", "Select the optimum casing string for a given well, given the pore pressure and fracture gradient at every depth in it.", "Predict the pressure at which a specific joint of casing will actually fail, to within the scatter of the published fits."]'::jsonb, 1, 'It is a capacity. The load is the next tier''s job and the design is the two together.'),
  ('casingtubing', 'beginner', 'module', 'm06-the-associate-reading', 14, 'What is the first question the next tier answers that this one cannot?', '["How much pressure is actually inside and outside the pipe, and how much weight is hanging at each depth.", "Which grade is the cheapest that passes.", "Whether the connection will seal against the internal pressure, which the efficiency table deliberately does not address.", "How much wall the drillstring will remove from the casing while the next hole section is being drilled through it."]'::jsonb, 0, 'A rating with no load is half a design.'),
  ('casingtubing', 'beginner', 'module', 'm06-the-associate-reading', 15, 'Which later course recomputes the ratings on a different wall?', '["Cementing, which sets the external column instead.", "Well Control, which sets the shoe pressure the gas kick case is built on and therefore the burst load rather than the rating.", "Torque, Drag and Casing Wear, which predicts how much wall the drillstring removes over the section.", "Completion Design, which takes the production casing as given and sizes the tubing and the packer to fit inside it."]'::jsonb, 2, 'A worn joint has less burst, less collapse and less tension, and none of the ratings here know.'),
  ('casingtubing', 'beginner', 'final', null, 1, 'A purchase order says 9-5/8 inch 47 lb/ft L-80 BTC. Which part of that does the burst formula read?', '["All four items, since each enters one of the four ratings.", "The diameter and the wall behind the 47, and the 80 behind the L, and nothing else on the line.", "The 47 directly, because the nominal weight fixes the steel area and the burst rating is proportional to that area.", "The BTC, because the connection efficiency is applied to the internal yield pressure as well as to the tensile capacity."]'::jsonb, 1, 'The weight names the row and the connection enters joint strength only.'),
  ('casingtubing', 'beginner', 'final', null, 2, 'Two joints have the same outside diameter and different nominal weights. What else must differ?', '["The grade, which is what the weight encodes.", "Only the bore, because API holds the wall constant within a nominal size and varies the inside diameter to set the weight.", "The wall, and therefore the bore as well, because the outside diameter is fixed and only one of the three can be free.", "The wall and the bore, since the diameter is fixed and the steel area has to change to change the weight."]'::jsonb, 3, 'Heavier means thicker, which means a smaller bore for the next section to be run through.'),
  ('casingtubing', 'beginner', 'final', null, 3, 'You need three millimetres more bore on a 9-5/8 inch string. What are you giving up?', '["About a millimetre and a half of wall on each side, and with it burst, collapse and tension together.", "Nothing, since the bore is set by the diameter alone.", "Only collapse, because the burst and tension ratings are set by the steel area rather than by the wall thickness directly.", "Roughly three millimetres of wall, since the bore is the outside diameter less the wall rather than less twice the wall."]'::jsonb, 0, 'The bore between the 47 and 53.5 lb/ft rows differs by 0.0037084000000000006 m in total.'),
  ('casingtubing', 'beginner', 'final', null, 4, 'Which two catalog rows would a formula treat as identical pipe?', '["Any two rows with the same nominal weight.", "Two rows with the same ratio of diameter to wall, since that is the only number the collapse calculation reads from a pipe.", "Two rows with the same diameter and wall at grades of the same yield, such as L-80 and N-80.", "Two rows of the same grade and weight in different nominal sizes, since the ratings scale with the geometry proportionally."]'::jsonb, 2, 'The engine reads one property from a grade name and it is the yield strength.'),
  ('casingtubing', 'beginner', 'final', null, 5, 'Barlow''s formula contains no length. What cancelled it?', '["The assumption that the wall is thin compared with the diameter.", "The length appears on both sides of the equilibrium, once in the projected area and once in the wall area.", "The choice of the outside diameter rather than the mean, which removes the dependence on how much pipe was cut.", "The wall tolerance factor, which is defined as a fraction per unit length and therefore divides the length back out again."]'::jsonb, 1, 'Cancelling it is what leaves a formula in three quantities.'),
  ('casingtubing', 'beginner', 'final', null, 6, 'A rating is quoted as 87.5 percent of a Barlow value. What is the other 12.5 percent?', '["The permitted undertolerance on the wall, so the rating applies to every joint rather than to an average one.", "A design factor applied by the operator, not by API.", "The difference between the Barlow approximation and the exact Lame solution at the wall ratios found in casing strings.", "An allowance for wear, since a joint that has had a drillstring turning inside it has lost part of its original wall."]'::jsonb, 0, 'Counting it as a safety factor is how 12.5 percent of margin gets used twice.'),
  ('casingtubing', 'beginner', 'final', null, 7, 'You compute a burst rating on the minimum wall and a colleague uses the nominal wall. Whose number is larger and by how much?', '["Yours, because a thinner wall gives a higher hoop stress.", "Theirs, by 12.5 percent, since the wall enters the formula linearly and the tolerance is 12.5 percent of the wall.", "Theirs, by one seventh, because dividing by 0.875 multiplies by about 1.1428571428571428.", "Neither, because the tolerance cancels once the design factor of 1.1 is applied to both answers before comparison."]'::jsonb, 2, 'Twelve and a half percent off gives an answer 14.3 percent lower, not 12.5.'),
  ('casingtubing', 'beginner', 'final', null, 8, 'Which rating would a thick walled cylinder solution change most?', '["Collapse, which is where the wall ratio matters most.", "Pipe body yield, since the axial stress is not uniform across a thick wall and the average understates the peak value.", "Burst, since the exact Lame hoop stress at the bore exceeds the Barlow average and the difference grows as the wall thickens.", "Burst, because Barlow averages a hoop stress that is really highest at the bore."]'::jsonb, 3, 'At the ratios in this catalog the difference is a few percent and Barlow is on the conservative side.'),
  ('casingtubing', 'beginner', 'final', null, 9, 'A section of 9-5/8 inch 53.5 lb/ft L-80 is run on long thread. What fraction of its steel is unavailable?', '["None, because the coupling is thicker than the pipe body.", "Fifteen percent of the pipe body yield, which on this joint is about 830 kN of capacity.", "Twenty five percent, which is the customary allowance for a threaded connection of any kind on a casing string.", "Fifteen percent of the wall thickness, which then propagates into the burst and collapse ratings as well as the tension one."]'::jsonb, 1, 'The joint strength is the pipe body yield times an efficiency of 0.85.'),
  ('casingtubing', 'beginner', 'final', null, 10, 'Why is a casing string usually strongest at the top?', '["Because the tension there is highest, since everything below is hanging off that joint.", "Because the collapse load is highest near surface.", "Because the top joints are the ones that see the full shut-in surface pressure during a gas kick, which is a burst load.", "Because the wellhead applies a bending moment that the upper joints must carry in addition to the axial and pressure loads."]'::jsonb, 0, 'The collapse argument runs the other way, and reconciling the two is what makes a tapered string a design.'),
  ('casingtubing', 'beginner', 'final', null, 11, 'Which two loads pull a casing string design in opposite directions?', '["Burst and collapse, which are the same subtraction.", "Burst, which is worst at the top on a gas kick, and tension, which is also worst at the top, so both favour the same fix.", "Tension, which is worst at the top, and collapse, which is worst at the bottom.", "Collapse and triaxial, because the derating from tension reduces collapse exactly where the triaxial number is already worst."]'::jsonb, 2, 'That is why a tapered string exists rather than a single grade and weight throughout.'),
  ('casingtubing', 'beginner', 'final', null, 12, 'A joint has a ratio of diameter to wall of 45. Which collapse regime is it most likely in?', '["Yield, because that regime covers the widest range.", "Elastic, because every transition to elastic boundary in the catalog is below about 43.", "Plastic, which holds 143 of the 280 combinations in the catalog and is therefore the most likely answer by frequency.", "Transition, since a ratio of 45 sits between the plastic and elastic boundaries at every grade the catalog carries."]'::jsonb, 1, 'The highest of the three third boundaries is 42.64275646019621 at H-40.'),
  ('casingtubing', 'beginner', 'final', null, 13, 'You are told a joint is in the yield collapse regime. What follows about its grade sensitivity?', '["It has none, as in the elastic regime.", "It has some, but less than in the plastic regime, because the yield regime formula contains the ratio squared as well.", "Its collapse rises with the grade in direct proportion, exactly as burst and pipe body yield do on the same joint.", "Its collapse is proportional to the yield strength, so a higher grade buys collapse at full exchange rate."]'::jsonb, 3, 'That is the only regime where collapse behaves like the other three ratings.'),
  ('casingtubing', 'beginner', 'final', null, 14, 'Why do the collapse regime boundaries fall as the yield strength rises?', '["Because a stronger pipe reaches the elastic buckling pressure before it reaches its own yield pressure.", "Because the coefficients A, B and C all fall with the yield.", "Because the published fits used thinner pipe at the higher grades, which biases the fitted boundaries toward lower slenderness.", "Because the elastic collapse pressure rises with the grade, which pushes the crossing with the yield curve to a lower ratio."]'::jsonb, 0, 'The buckling pressure does not move with the grade and the yield pressure does.'),
  ('casingtubing', 'beginner', 'final', null, 15, 'Which check would catch a mistranscribed 5C3 coefficient most reliably?', '["Comparing one collapse value against a published table.", "Checking that collapse falls monotonically as the ratio of diameter to wall rises, across the whole catalog at every grade.", "Probing either side of each regime boundary and requiring the two adjacent formulas to agree there.", "Verifying that the elastic collapse value matches the closed form, since that formula has no fitted coefficients in it."]'::jsonb, 2, 'Continuity is a property the system was constructed to have, so any error breaks it.'),
  ('casingtubing', 'beginner', 'final', null, 16, 'A section carries an axial stress of half its yield. What is its adjusted yield fraction?', '["Exactly one half, since the reduction is linear.", "About 0.6513878188659973, which is the value of the ellipse expression at a ratio of one half.", "About 0.75, which is one less three quarters of the ratio, taking the first term of the bracket on its own.", "About 0.87, the square root of three quarters, which is the value the expression takes when the linear term is neglected."]'::jsonb, 1, 'It is below the straight line between the endpoints at every value in between.'),
  ('casingtubing', 'beginner', 'final', null, 17, 'The adjusted yield fractions are the same for every grade. Why?', '["Because the expression depends on the axial stress only through its ratio to the yield strength.", "Because API publishes one table for all grades.", "Because the von Mises criterion is grade independent, so the whole combined loading adjustment is a geometric statement.", "Because the yield strength cancels between the numerator and the denominator once the collapse formula has been applied."]'::jsonb, 0, 'Multiply the fraction by whatever yield strength the grade has and you get the adjusted value.'),
  ('casingtubing', 'beginner', 'final', null, 18, 'A pipe loses exactly the same fraction of collapse as it loses of yield. Which regime is it in?', '["The elastic regime, where both losses are zero.", "The plastic regime, since its published fit was constructed to preserve proportionality with the yield strength exactly.", "The yield regime, because the collapse pressure there is twice the yield times a function of the ratio and nothing else.", "The yield regime, whose formula is linear in the yield strength and passes the derating straight through."]'::jsonb, 3, 'In the two middle regimes only part of the loss comes through, and in the elastic regime none of it does.'),
  ('casingtubing', 'beginner', 'final', null, 19, 'Why does tension move a pipe toward the yield collapse regime rather than the elastic one?', '["Because tension thins the wall and raises the ratio.", "Because the elastic formula is the only one that does not contain the yield strength, so it is the first to stop applying.", "Because a derated pipe behaves like a lower grade one, and low grade pipe has higher regime boundaries.", "Because the adjusted yield falls faster than the boundaries do, so the pipe crosses each boundary from above rather than below."]'::jsonb, 2, 'The boundaries rise past the pipe''s fixed ratio, one after another.'),
  ('casingtubing', 'beginner', 'final', null, 20, 'An engine returns a collapse of zero and a regime named yield-exhausted. What has happened?', '["The axial stress reached the yield strength, so there is no strength left to resist an external pressure.", "The inputs were invalid and the call failed silently.", "The pipe entered a fifth physical regime in which the wall yields axially before any radial mechanism can develop at all.", "The external pressure exceeded the rating, so the engine reported the remaining capacity as zero rather than a negative."]'::jsonb, 0, 'The fifth name is a flag that travels with the answer instead of being logged somewhere and lost.'),
  ('casingtubing', 'beginner', 'final', null, 21, 'Which single property of steel makes elastic collapse grade independent?', '["Density, which is identical across the grade table.", "Young''s modulus, which is essentially the same for every grade while strength varies by a factor of three.", "The Poisson ratio, which appears in the elastic buckling solution and does not vary measurably between casing grades.", "The thermal expansion coefficient, which is what sets the residual stress from manufacture and therefore the ovality."]'::jsonb, 1, 'Buckling depends on stiffness, and yielding depends on strength.'),
  ('casingtubing', 'beginner', 'final', null, 22, 'On a row that is elastic at every grade, what does moving from K-55 to P-110 change?', '["Everything doubles, since all four scale with the yield.", "Collapse rises by about a third while burst and tension double, which is the usual pattern in the plastic regime as well.", "Burst and pipe body yield both double exactly, and collapse is unchanged because the elastic formula has no yield in it.", "Burst and tension double, and collapse does not move at all."]'::jsonb, 3, 'The only thing that buys collapse in that regime is wall thickness.'),
  ('casingtubing', 'beginner', 'final', null, 23, 'Which is the better answer to a collapse shortfall on a 20 inch surface string?', '["A higher grade, which raises every rating in proportion.", "A lower design factor, since the published collapse rating already carries the conservatism of a minimum from a test population.", "A heavier row of the same size, because wall thickness is the only lever the elastic formula responds to.", "A shorter section, because the collapse load is the mud hydrostatic and it grows in direct proportion with the depth."]'::jsonb, 2, 'The heavier row moves the ratio, which is the only input the elastic formula has.'),
  ('casingtubing', 'beginner', 'final', null, 24, 'Two thin surface joints differ only in steel. Where does the stronger one gain anything?', '["A wider band of axial tension over which the collapse rating stays flat instead of starting to fall.", "Nothing whatsoever, at any level of axial load.", "A proportional increase in collapse once the pipe is in tension, because the adjusted yield reintroduces the grade dependence.", "A smaller ratio of diameter to wall, since a higher grade meets the same nominal weight at a slightly thicker wall."]'::jsonb, 0, 'H-40 leaves the regime at about 27 percent of yield and Q-125 at about 84.'),
  ('casingtubing', 'beginner', 'final', null, 25, 'Which catalog quantity does the engine use only for the hanging weight?', '["The inside diameter, used only for the drift check.", "The nominal weight in pounds per foot, converted once to kilograms per metre at the catalog.", "The outside diameter, which enters the axial profile through the buoyancy factor and nowhere else in the four ratings.", "The connection name, which is looked up once to get an efficiency and then plays no part in any other calculation."]'::jsonb, 1, 'Every rating uses the wall and the diameter, and none of them uses the weight.'),
  ('casingtubing', 'beginner', 'final', null, 26, 'Why does the catalog integrity test allow a five millimetre reconstruction error?', '["Because the mill tolerance on the wall is 12.5 percent.", "Because the engine stores metres and the published values are inches, and the conversion constant is held to seven figures.", "Because the published API table rounds the wall and the inside diameter independently of each other.", "Because the outside diameter is a nominal size rather than a measurement, and real pipe is permitted to vary around it."]'::jsonb, 2, 'Any code that derives one dimension from the other two will disagree with the table by a fraction of a millimetre.'),
  ('casingtubing', 'beginner', 'final', null, 27, 'What would you check a screening rating against before ordering pipe?', '["The manufacturer''s data sheet, the wear prediction and the service environment, and expect some candidates to be eliminated.", "Nothing, since the published ratings are minimums.", "The design factors, which is the only step between a rating and a decision once the load cases have been established.", "A second implementation of the same four formulas, since agreement between two codes is what validates a screening number."]'::jsonb, 0, 'A screening tool that eliminates the right ninety percent has done its job.'),
  ('casingtubing', 'beginner', 'final', null, 28, 'Which omission from the ratings would a purchase order alone never reveal?', '["The grade, which is stated on the order.", "The connection sealing rating, which is available from the connection licensor and can be requested at the time of ordering.", "The wear, since the amount of wall removed depends on rotating hours and side force rather than on anything the order states.", "The wear the drillstring will inflict, because it depends on the drilling programme rather than on the pipe."]'::jsonb, 3, 'It is the subject of a different course and it changes every one of the four ratings.'),
  ('casingtubing', 'beginner', 'final', null, 29, 'You have two candidate joints with equal collapse and different burst. Which check decides between them?', '["The cheaper one, since the ratings are already equal.", "Whichever load case is closest to its design factor, which is a load question rather than a rating one.", "The collapse check, because equal collapse ratings at different burst ratings implies different regimes and therefore different risk.", "The triaxial check, since it is the only one that sees all three stresses and therefore breaks ties the other three cannot."]'::jsonb, 1, 'A rating with no load is half a design, and the tie is broken in the next tier.'),
  ('casingtubing', 'beginner', 'final', null, 30, 'A colleague says a joint is rated to 47 MPa. What is your first question?', '["Which of the four ratings that is, since burst and collapse on one joint can differ by a factor of two.", "Which grade the joint is, since that sets all four.", "Whether the number includes the design factor, since a rating and an allowable are different quantities and are often confused.", "Whether it is quoted in megapascals or in pounds per square inch, since the published tables use the latter throughout."]'::jsonb, 0, 'The definition attached to a rating is the important half of it.'),
  ('casingtubing', 'beginner', 'final', null, 31, 'Which pair of ratings always changes together by the same factor?', '["Burst and collapse, both being pressures on the wall.", "Burst and joint strength, because the connection efficiency is applied to the internal yield pressure as well as to tension.", "Pipe body yield and joint strength, because the second is the first times a fixed efficiency.", "Collapse and pipe body yield, since the combined loading adjustment links them through the same adjusted yield strength."]'::jsonb, 2, 'Burst also scales with the grade, but it does not carry the efficiency.'),
  ('casingtubing', 'beginner', 'final', null, 32, 'A pipe sits just below a regime boundary and you raise the grade. What can happen?', '["Nothing, since the regime depends on geometry alone.", "The pipe moves down a regime, because a higher grade behaves like a thicker one for the purposes of the collapse calculation.", "The boundary moves with the pipe, since both are computed from the same ratio of diameter to wall at the chosen grade.", "The boundary can fall past the pipe''s ratio, moving it into the next regime up."]'::jsonb, 3, 'And the next regime up is always less sensitive to the grade, which is a point of diminishing return.'),
  ('casingtubing', 'beginner', 'final', null, 33, 'Where in a rating table would you look first for a joint that must survive a full evacuation?', '["The burst column, since evacuation is a pressure load.", "The collapse column, and then at the regime, before deciding whether grade or wall is the lever.", "The joint strength column, because an evacuated string is buoyed less and therefore carries more axial load at every depth.", "The pipe body yield column, since a collapsed joint has yielded and the yield capacity is what determines when it does so."]'::jsonb, 1, 'Full evacuation is a pure collapse case and the inside pressure is zero throughout.'),
  ('casingtubing', 'beginner', 'final', null, 34, 'Two pipes have the same collapse rating. One is elastic and one is plastic. What differs?', '["How each responds to grade and to tension: the elastic one responds to neither and the plastic one to both.", "Nothing, since the rating is the same number.", "Only the published tolerance, since the elastic formula is exact and the plastic one carries the scatter of the fitted data.", "The design factor that should be applied, since an empirical regime warrants more margin than a closed form one does."]'::jsonb, 0, 'The number is the same and the advice about how to improve it is opposite.'),
  ('casingtubing', 'beginner', 'final', null, 35, 'Which statement about the published yield strength is correct?', '["It is the mean of the mill''s production for that grade.", "It is the stress at which the steel fractures, which is why the ratings are described as yield rather than rupture values.", "It is a minimum, so every rating computed from it is a lower bound on what the joint will do.", "It is a nominal figure with no statistical definition, chosen so that the grade names come out as round numbers in ksi."]'::jsonb, 2, 'Real pipe runs above it, often well above, which is the right direction for a design number to be wrong in.'),
  ('casingtubing', 'beginner', 'final', null, 36, 'Why is the wall the number to trust when the three dimensions are inconsistent?', '["Because it is measured most precisely at the mill.", "Because every rating formula in the tier uses it, and the inside diameter is used only for the area and the drift.", "Because the outside diameter is a nominal size rather than a measurement, so it cannot be used to correct either of the others.", "Because the inside diameter is rounded to three decimal places in inches while the wall is held to four in the same table."]'::jsonb, 1, 'The published table rounds all three separately, so a millimetre of inconsistency is normal.'),
  ('casingtubing', 'beginner', 'final', null, 37, 'What is the practical consequence of the collapse fits being empirical?', '["They cannot be used outside the fitted range.", "They must be recomputed for every new grade, since the coefficient polynomials are fitted per grade rather than in the yield.", "They apply only to seamless pipe, since the test programme that produced them contained no electric welded product at all.", "The published values carry the scatter of a test population, so a design factor of 1.0 is defensible on them."]'::jsonb, 3, 'Stacking a large design factor on a number that is already a minimum double counts the conservatism.'),
  ('casingtubing', 'beginner', 'final', null, 38, 'In the elastic regime, which two inputs does the collapse pressure depend on?', '["The outside diameter and the wall, through their ratio, and nothing else about the pipe or the steel.", "The yield strength and the ratio of diameter to wall.", "The wall thickness in absolute terms and the Young''s modulus, both of which enter the elastic buckling solution directly.", "The ratio of diameter to wall and the axial stress, since the combined loading adjustment applies in every regime equally."]'::jsonb, 0, 'One number in, one number out, and the constant of 46950000 in front of it.'),
  ('casingtubing', 'beginner', 'final', null, 39, 'You are asked which grade to order for a string that is burst critical. What can you say precisely?', '["That the highest grade available is always correct.", "That the grade should be chosen so the pipe sits in the plastic collapse regime, which is where the ratings are best characterised.", "That burst rises in exact proportion with the yield strength, so the exchange rate between money and rating is fixed.", "That the answer depends on the collapse regime, since a higher grade may buy nothing and the wall would be the better lever."]'::jsonb, 2, 'That is precisely the case where the answer is simple, and it is simple because collapse is not the binding check.'),
  ('casingtubing', 'beginner', 'final', null, 40, 'What is the single most useful habit this tier teaches?', '["Applying the wall tolerance factor to every rating.", "Asking which collapse regime a joint is in before saying anything about how to make it stronger.", "Computing all four ratings before any load case is considered, so that the capacities are established independently of the loads.", "Checking that the inside diameter plus twice the wall reconstructs the outside diameter to within the API rounding tolerance."]'::jsonb, 1, 'Two engineers who agree on the number and disagree on the regime will give opposite advice.'),
  ('casingtubing', 'beginner', 'final', null, 41, 'A joint''s ratio of diameter to wall is 17.66 and its grade''s yield to plastic boundary is 13.38. Where is it?', '["In the yield regime, being the thicker of the two.", "In the transition regime, because a ratio below twenty is always between the second and third boundaries at any grade.", "In the plastic regime, which is where a ratio between the yield boundary and the plastic to transition one always falls.", "In the plastic regime, since it is above the first boundary and below the second one for that grade."]'::jsonb, 3, 'That is the 9-5/8 inch 53.5 lb/ft joint at L-80, and it is the thickest casing row in the catalog.'),
  ('casingtubing', 'beginner', 'final', null, 42, 'What is the correct reading of a collapse rating quoted without a regime?', '["A complete answer, since the regime is only a label.", "An incomplete answer, because the published collapse value is defined only once the applicable formula has been identified.", "A number that must be recomputed, since a rating quoted without its regime cannot be checked against any published table.", "A number you can use and cannot yet advise on, because the fix for a shortfall depends on the regime."]'::jsonb, 3, 'The number is the same in every regime. The advice is not.');
